#pragma once

#include <cstring>

namespace neos::python_runtime::detail::asyncio_protocols_docs
{
    struct entry { char const* name; char const* doc; };
    inline entry const sDocs[] =
    {
        { "", "Abstract Protocol base classes." },
        { "BaseProtocol", "Common base class for protocol interfaces.\n\nUsually user implements protocols that derived from BaseProtocol\nlike Protocol or ProcessProtocol.\n\nThe only case when BaseProtocol should be implemented directly is\nwrite-only transport like write pipe\n" },
        { "BaseProtocol.connection_made", "Called when a connection is made.\n\nThe argument is the transport representing the pipe connection.\nTo receive data, wait for data_received() calls.\nWhen the connection is closed, connection_lost() is called.\n" },
        { "BaseProtocol.connection_lost", "Called when the connection is lost or closed.\n\nThe argument is an exception object or None (the latter\nmeaning a regular EOF is received or the connection was\naborted or closed).\n" },
        { "BaseProtocol.pause_writing", "Called when the transport's buffer goes over the high-water mark.\n\nPause and resume calls are paired -- pause_writing() is called\nonce when the buffer goes strictly over the high-water mark\n(even if subsequent writes increases the buffer size even\nmore), and eventually resume_writing() is called once when the\nbuffer size reaches the low-water mark.\n\nNote that if the buffer size equals the high-water mark,\npause_writing() is not called -- it must go strictly over.\nConversely, resume_writing() is called when the buffer size is\nequal or lower than the low-water mark.  These end conditions\nare important to ensure that things go as expected when either\nmark is zero.\n\nNOTE: This is the only Protocol callback that is not called\nthrough EventLoop.call_soon() -- if it were, it would have no\neffect when it's most needed (when the app keeps writing\nwithout yielding until pause_writing() is called).\n" },
        { "BaseProtocol.resume_writing", "Called when the transport's buffer drains below the low-water mark.\n\nSee pause_writing() for details.\n" },
        { "BufferedProtocol", "Interface for stream protocol with manual buffer control.\n\nEvent methods, such as `create_server` and `create_connection`,\naccept factories that return protocols that implement this interface.\n\nThe idea of BufferedProtocol is that it allows to manually allocate\nand control the receive buffer.  Event loops can then use the buffer\nprovided by the protocol to avoid unnecessary data copies.  This\ncan result in noticeable performance improvement for protocols that\nreceive big amounts of data.  Sophisticated protocols can allocate\nthe buffer only once at creation time.\n\nState machine of calls:\n\n  start -> CM [-> GB [-> BU?]]* [-> ER?] -> CL -> end\n\n* CM: connection_made()\n* GB: get_buffer()\n* BU: buffer_updated()\n* ER: eof_received()\n* CL: connection_lost()\n" },
        { "BufferedProtocol.get_buffer", "Called to allocate a new receive buffer.\n\n*sizehint* is a recommended minimal size for the returned\nbuffer.  When set to -1, the buffer size can be arbitrary.\n\nMust return an object that implements the\n:ref:`buffer protocol <bufferobjects>`.\nIt is an error to return a zero-sized buffer.\n" },
        { "BufferedProtocol.buffer_updated", "Called when the buffer was updated with the received data.\n\n*nbytes* is the total number of bytes that were written to\nthe buffer.\n" },
        { "BufferedProtocol.eof_received", "Called when the other end calls write_eof() or equivalent.\n\nIf this returns a false value (including None), the transport\nwill close itself.  If it returns a true value, closing the\ntransport is up to the protocol.\n" },
        { "DatagramProtocol", "Interface for datagram protocol." },
        { "DatagramProtocol.datagram_received", "Called when some datagram is received." },
        { "DatagramProtocol.error_received", "Called when a send or receive operation raises an OSError.\n\n(Other than BlockingIOError or InterruptedError.)\n" },
        { "Protocol", "Interface for stream protocol.\n\nThe user should implement this interface.  They can inherit from\nthis class but don't need to.  The implementations here do\nnothing (they don't raise exceptions).\n\nWhen the user wants to requests a transport, they pass a protocol\nfactory to a utility function (e.g., EventLoop.create_connection()).\n\nWhen the connection is made successfully, connection_made() is\ncalled with a suitable transport object.  Then data_received()\nwill be called 0 or more times with data (bytes) received from the\ntransport; finally, connection_lost() will be called exactly once\nwith either an exception object or None as an argument.\n\nState machine of calls:\n\n  start -> CM [-> DR*] [-> ER?] -> CL -> end\n\n* CM: connection_made()\n* DR: data_received()\n* ER: eof_received()\n* CL: connection_lost()\n" },
        { "Protocol.data_received", "Called when some data is received.\n\nThe argument is a bytes object.\n" },
        { "Protocol.eof_received", "Called when the other end calls write_eof() or equivalent.\n\nIf this returns a false value (including None), the transport\nwill close itself.  If it returns a true value, closing the\ntransport is up to the protocol.\n" },
        { "SubprocessProtocol", "Interface for protocol for subprocess calls." },
        { "SubprocessProtocol.pipe_data_received", "Called when the subprocess writes data into stdout/stderr pipe.\n\nfd is int file descriptor.\ndata is bytes object.\n" },
        { "SubprocessProtocol.pipe_connection_lost", "Called when a file descriptor associated with the child process is\nclosed.\n\nfd is the int file descriptor that was closed.\n" },
        { "SubprocessProtocol.process_exited", "Called when subprocess has exited." },
    };
    inline char const* doc(char const* aName)
    {
        for (auto const& e : sDocs)
            if (std::strcmp(e.name, aName) == 0)
                return e.doc;
        return nullptr;
    }
}
